import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import Checkout from './pages/Checkout';

function App() {
  return (
    <BrowserRouter>
      <Routes>
        {/* Redirect root → checkout */}
        <Route path="/" element={<Navigate to="/checkout" />} />

        {/* Checkout page */}
        <Route path="/checkout" element={<Checkout />} />

        {/* Fallback */}
        <Route path="*" element={<Navigate to="/checkout" />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
